pm.test("Všechny proměnné v těle a URL požadavku jsou nahrazeny", function () {
    pm.expect(
        pm.variables.get("local_varsCheck"),
        pm.variables.get("local_varsDetail")
    ).to.equal("OK");
});

// 1. Základní kontrola na status kód (očekáváme vždy 200)
pm.test("Status kód je 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Chytrá univerzální aserce pro datově řízené testy (Data-Driven)
const nazevSvatku = pm.iterationData.get("holidayName");
const jeToNegativniTest = nazevSvatku.includes("Negativní test");

if (jeToNegativniTest) {
    // Aserce pro 40. iteraci (Běžný pracovní den)
    pm.test("Negativní test: Dovolená se úspěšně zapsala", function () {
        var jsonData = pm.response.json();
        pm.expect(jsonData.MarkedDays).to.be.an('array').that.is.not.empty;
    });
} else  {
    // Aserce pro prvních 39 iterací (Skutečné svátky)
    pm.test("Očekáváno: Žádný zápis dovolené během státního svátku", function () {
        var jsonData = pm.response.json();
        
        // Zpráva, která se vypíše v případě selhání (Custom error message)
        var detailChyby = "Chyba! API nezahodilo státní svátek a zapsalo ho do databáze.";
        
        pm.expect(jsonData.MarkedDays, detailChyby).to.be.an('array').that.is.empty;
    });
}

//return; // Dočasné vypnutí skriptu

const rawBody = pm.request.body ? (pm.request.body.raw || "") : "";
const rawUrl = pm.request.url.toString();

const resolvedBody = pm.variables.replaceIn(rawBody);
const resolvedUrl = pm.variables.replaceIn(rawUrl);

const unresolved = [];
if (resolvedBody.includes("{{")) unresolved.push("tělo: " + resolvedBody);
if (resolvedUrl.includes("{{")) unresolved.push("URL: " + resolvedUrl);

pm.variables.set("local_varsCheck", unresolved.length === 0 ? "OK" : "CHYBA");
pm.variables.set("local_varsDetail", unresolved.join(" | "));
console.log("[kontrola proměnných]", pm.variables.get("local_varsCheck"));
